  return ((isa<ConstantInt>(SI->getTrueValue()) &&
           (dyn_cast<ConstantInt>(SI->getTrueValue())->isOne())) ||
          (isa<ConstantInt>(SI->getFalseValue()) &&
           (dyn_cast<ConstantInt>(SI->getFalseValue())->isNullValue())));
}

