+  double Re;
+  double Im;
+  Complex(double Re = 0.0, double Im = 0.0) : Re(Re), Im(Im) {}
+  Complex &operator+=(const Complex &RHS) {
+    Re += RHS.Re;
+    Im += RHS.Im;
+    return *this;
